/** Exact-sequence structure context, with separate acquisition, prediction and assessment evidence. */
final class StudyProteinStructures implements StudyOperationExecutor {
    private static final String AF="https://alphafold.ebi.ac.uk/faq",UNIPROT="https://www.uniprot.org/help/sequence_processing";
    static final String CAVEAT="Protein structures and pLDDT/PAE supply model context, not evidence of pathogenicity, binding, causality or activity. pLDDT is local confidence, not a P value or an assay effect; PAE is directional. Sequence identity does not establish assay specificity, mature processing, a functional isoform switch or a complex interface. Retrieval is distinct from a new prediction; configured software/weights/MSA/template identities are source declarations unless separately verified. All declared models/seeds and missing/incompatible inputs are retained without choosing the most confident model.";
    private final StudyPublicEvidence client;
    StudyProteinStructures(){this(new StudyPublicEvidence());}
    StudyProteinStructures(StudyPublicEvidence client){this.client=client;}
    @Override public Result execute(Context c) throws Exception {
        Files.createDirectories(c.outputDirectory());var p=StudyProteinPolicy.resolve(map(StudyResultTables.analysis(c).get("protein_structure")));var summary=new LinkedHashMap<String,Object>();summary.put("required_manuscript_caveat",CAVEAT);summary.put("source_scope",p.get("scope"));summary.put("assessment_only","protein_structure_assessment".equals(c.operation().get("type")));summary.put("new_prediction_processes",0);summary.put("prediction_batches_reused",0);summary.put("structure_retrievals",0);
        if(!Boolean.TRUE.equals(p.get("enabled")))return finish(c,p,summary,true,false,"Protein structure analysis is disabled in the registered protocol");
        StudyProteinInputs.Loaded inputs;try{inputs=StudyProteinInputs.load(c,p);}catch(IllegalArgumentException invalid){return finish(c,p,summary,false,false,invalid.getMessage());}summary.put("input_sources",inputs.sources());summary.put("requested_targets",inputs.targets().size());
        var rows=new ArrayList<Map<String,Object>>();var dispositions=new ArrayList<Object>();summary.put("target_dispositions",dispositions);
        if(inputs.targets().size()>integer(p,"max_targets")){for(var t:inputs.targets())dispositions.add(disposition(t,"target_budget_exceeded","Complete requested scope exceeds max_targets; no confidence/significance-ranked subset was selected"));return finish(c,p,summary,false,false,"Protein target scope exceeds the registered bound; narrow it with an outcome-independent protocol or increase the bound");}
        boolean complete=true;int targetOrdinal=0,completedTargets=0;
        for(var target:inputs.targets()){
            Path folder=c.outputDirectory().resolve("proteins").resolve(String.format("%04d",++targetOrdinal));Files.createDirectories(folder);var targetSummary=new LinkedHashMap<String,Object>();targetSummary.putAll(disposition(target,"pending",""));targetSummary.put("directory",relative(c,folder));targetSummary.put("assay_mapping_status",map(target.get("assay_mapping")).getOrDefault("status","unknown"));dispositions.add(targetSummary);
            try{
                String protein=text(target.get("protein_id"));if(protein.isBlank())throw new IllegalArgumentException("No unambiguous declared protein accession for this feature; supply protein/isoform and assay mapping instead of substituting a gene symbol");
                int taxon=target.get("taxon_id") instanceof Number n?n.intValue():0;if(taxon<1)throw new IllegalArgumentException("Declare the assayed taxon_id before selecting a protein sequence/model");
                String sequence=sequence(c,p,target,inputs.sequences(),folder,targetSummary);targetSummary.put("sequence_sha256",StudyFindingInventory.hash(sequence));targetSummary.put("target_length",sequence.length());Files.writeString(folder.resolve("target.fasta"),">target\n"+sequence+"\n");
                var models=new ArrayList<Map<String,Object>>();for(Object raw:list(target.get("models")))models.add(map(raw));
                if(models.isEmpty()&&!Boolean.TRUE.equals(summary.get("assessment_only"))&&Boolean.TRUE.equals(p.get("retrieve")))models.addAll(retrieve(c,p,target,sequence,folder,targetSummary));
                StudyProteinPrediction.Batch batch=null;
                if(models.isEmpty()&&!Boolean.TRUE.equals(summary.get("assessment_only"))&&Boolean.TRUE.equals(map(p.get("prediction")).get("enabled"))){batch=new StudyProteinPrediction().run(c,p,target,sequence,inputs.sequences(),folder.resolve("prediction"));models.addAll(batch.models());targetSummary.put("prediction_batch",Map.of("identity",batch.identity(),"reused",batch.reused(),"complete",batch.complete(),"reason",batch.reason()));if(batch.reused())increment(summary,"prediction_batches_reused");else if(Files.isRegularFile(batch.directory().resolve("process-result.yaml")))increment(summary,"new_prediction_processes");}
                if(models.isEmpty())throw new IllegalArgumentException(batch==null?"No compatible exact structure is available; supply a model or configure an appropriate predictor":batch.reason());
                if(models.size()>integer(p,"max_models_per_target"))throw new IllegalArgumentException("All candidate models are retained, but their number exceeds max_models_per_target; no favorable model was selected");
                var modelDispositions=new ArrayList<Object>();targetSummary.put("models",modelDispositions);boolean valid=true;int modelOrdinal=0;var ids=new LinkedHashSet<String>();
                for(var model:models){Path modelFolder=folder.resolve("models").resolve(String.format("%03d",++modelOrdinal));Files.createDirectories(modelFolder);var md=new LinkedHashMap<String,Object>();md.put("model_id",model.getOrDefault("id",""));md.put("directory",relative(c,modelFolder));modelDispositions.add(md);try{if(!ids.add(text(model.get("id"))))throw new IllegalArgumentException("Duplicate model ID; every source model needs a distinct identity");var row=assess(c,p,target,sequence,inputs.sequences(),model,modelFolder);rows.add(row);md.put("status","assessed");md.put("sequence_match",row.get("sequence_match"));md.put("coverage",row.get("coverage"));if(!"eligible_context".equals(row.get("status"))){valid=false;md.put("reason",row.get("limitations"));}}catch(IllegalArgumentException|IOException invalid){valid=false;md.put("status","incompatible_or_incomplete");md.put("reason",invalid.getMessage()==null?invalid.getClass().getSimpleName():invalid.getMessage());}}
                if(batch!=null){valid&=batch.complete();if(valid)StudyProteinPrediction.seal(batch);}
                targetSummary.put("status",valid?"complete":"incomplete");targetSummary.put("reason",valid?"Every declared model assessed; source/assay caveats retained":"Inspect every model disposition; partial evidence is retained without a complete-target claim");if(valid)completedTargets++;else complete=false;
            }catch(IllegalArgumentException|IOException invalid){complete=false;targetSummary.put("status","input_or_resource_needed");targetSummary.put("reason",invalid.getMessage()==null?invalid.getClass().getSimpleName():invalid.getMessage());}
        }
        summary.put("completed_targets",completedTargets);summary.put("assessed_models",rows.size());summary.put("structure_retrievals",dispositions.stream().map(StudyPublicEvidence::map).mapToInt(d->((Number)d.getOrDefault("retrieved_models",0)).intValue()).sum());summary.put("queries",client.requests());
        var columns=List.of("feature_id","dataset_id","protein_id","isoform_id","taxon_id","sequence_sha256","sequence_version","model_id","model_source","structure_kind","method","model_version","seed","chain","sequence_match","target_length","observed_residues","coverage","confidence_residues","mean_plddt","fraction_plddt_lt50","fraction_plddt_50_70","fraction_plddt_70_90","fraction_plddt_ge90","pae_dimension","assay_mapping_status","assay_mapping_source","assay_mapping_limitations","source_sha256","pae_sha256","status","limitations","directory");
        var table=new ArrayList<String[]>();for(var row:rows)table.add(columns.stream().map(k->text(row.getOrDefault(k,"NA"))).toArray(String[]::new));FollowupSupport.table(c.outputDirectory().resolve("protein-structures.tsv"),columns,table);
        return finish(c,p,summary,complete,!rows.isEmpty(),complete?"Sequence-bound protein context completed; confidence and source limitations remain explicit":"Protein context is partial; missing/incompatible models or resources remain prerequisites and independent analyses can continue");
    }
    private String sequence(Context c,Map<String,Object> p,Map<String,Object> target,Map<String,String> sequences,Path folder,Map<String,Object> summary)throws IOException {
        String protein=text(target.get("protein_id")),id=text(target.getOrDefault("sequence_id",protein));String sequence=sequences.get(id);
        if(sequence==null&&!sequences.isEmpty())throw new IllegalArgumentException("Supplied FASTA has no exact sequence_id "+id+"; use its full FASTA identifier, including any pipe-delimited accession");
        if(sequence==null){if(!Boolean.TRUE.equals(p.get("retrieve")))throw new IllegalArgumentException("Supply the exact target FASTA sequence; public retrieval is disabled");accession(protein);var reply=client.getText(c,"UniProt","https://rest.uniprot.org/uniprotkb/"+protein+".fasta",UNIPROT,"Obtain the declared public accession's exact sequence and taxon; no private sequence is transmitted",integer(p,"max_file_bytes"));if(!reply.ok())throw new IllegalArgumentException("Exact UniProt sequence unavailable: "+reply.status());String fasta=text(reply.data());var parsed=ProteinStructure.fasta(fasta,1,integer(p,"max_residues"));String header=parsed.keySet().iterator().next();String[] parts=header.split("\\|",-1);if(parts.length!=3||!parts[1].equals(protein))throw new IllegalArgumentException("UniProt FASTA accession/isoform differs from the requested accession; no canonical fallback is permitted");var matcher=java.util.regex.Pattern.compile("(?:^|\\s)OX=([0-9]+)(?:\\s|$)").matcher(fasta.lines().findFirst().orElse(""));if(!matcher.find()||Integer.parseInt(matcher.group(1))!=((Number)target.get("taxon_id")).intValue())throw new IllegalArgumentException("UniProt FASTA taxon does not match the registered assay taxon");sequence=parsed.values().iterator().next();Files.writeString(folder.resolve("uniprot-source.fasta"),fasta);summary.put("sequence_origin","retrieved_exact_public_UniProt_accession");summary.put("sequence_query_audit",reply.audit());var version=java.util.regex.Pattern.compile("(?:^|\\s)SV=([0-9]+)(?:\\s|$)").matcher(fasta.lines().findFirst().orElse(""));if(version.find())summary.put("public_sequence_version",version.group(1));}
        else summary.put("sequence_origin","supplied_exact_FASTA_identifier");
        if(sequence.length()>integer(p,"max_residues"))throw new IllegalArgumentException("Target sequence exceeds max_residues");return sequence;
    }
    private List<Map<String,Object>> retrieve(Context c,Map<String,Object> p,Map<String,Object> target,String sequence,Path folder,Map<String,Object> summary)throws IOException {
        String protein=text(target.get("protein_id"));accession(protein);var reply=client.get(c,"AlphaFold DB","https://alphafold.ebi.ac.uk/api/prediction/"+protein,AF,"Find exact accession, taxon and target-sequence models; retain other isoform candidates as incompatible rather than selecting the first hit");if(!reply.ok()){summary.put("retrieval_status",reply.status());return List.of();}
        var selected=new ArrayList<Map<String,Object>>();var inventory=new ArrayList<Object>();int ordinal=0;
        for(Object raw:list(reply.data())){var candidate=map(raw);String reason=!protein.equals(text(candidate.get("uniprotAccession")))?"different_accession_or_isoform":!text(target.get("taxon_id")).equals(text(candidate.get("taxId")))?"different_taxon":!sequence.equals(text(candidate.get("sequence")))?"different_target_sequence":"compatible_exact_sequence";inventory.add(Map.of("entry_id",text(candidate.get("entryId")),"accession",text(candidate.get("uniprotAccession")),"taxon_id",text(candidate.get("taxId")),"version",text(candidate.get("latestVersion")),"disposition",reason));if(reason.equals("compatible_exact_sequence"))selected.add(candidate);}
        write(folder.resolve("model-candidate-inventory.yaml"),inventory);summary.put("retrieval_metadata_audit",reply.audit());if(selected.size()>integer(p,"max_models_per_target"))throw new IllegalArgumentException("Exact provider models exceed max_models_per_target; all candidates are inventoried without confidence ranking");var models=new ArrayList<Map<String,Object>>();
        for(var candidate:selected){String cif=text(candidate.get("cifUrl")),pdb=text(candidate.get("pdbUrl")),url=cif.isBlank()?pdb:cif;if(url.isBlank())continue;artifactUrl(url);String id=text(candidate.get("entryId"));if(id.isBlank()||text(candidate.get("latestVersion")).isBlank())throw new IllegalArgumentException("Provider model lacks its entry/version identity");Path rawFolder=folder.resolve("retrieved").resolve(String.format("%03d",++ordinal));Files.createDirectories(rawFolder);write(rawFolder.resolve("provider-model.yaml"),candidate);var structure=client.getText(c,"AlphaFold DB",url,AF,"Download the versioned structure matching the declared accession, sequence and taxon",integer(p,"max_file_bytes"));if(!structure.ok())throw new IllegalArgumentException("Exact AlphaFold model download unavailable: "+structure.status());Path file=rawFolder.resolve(cif.isBlank()?"model.pdb":"model.cif");Files.writeString(file,text(structure.data()));var m=new LinkedHashMap<String,Object>();m.put("id",id+"-v"+candidate.get("latestVersion"));m.put("file",file.toAbsolutePath().toString());m.put("format",cif.isBlank()?"pdb":"cif");m.put("model_number",1);m.put("sequence_start",1);m.put("chain",candidate.getOrDefault("chainId","A"));m.put("confidence_source","b_factor_plddt");m.put("confidence_provenance","AlphaFold DB: model B-factor field stores pLDDT; "+AF);m.put("structure_kind","alphafold_prediction");m.put("method",candidate.getOrDefault("toolUsed","AlphaFold DB source-declared method"));m.put("model_version",text(candidate.get("latestVersion")));m.put("source","retrieved_AlphaFold_DB");m.put("source_sequence_sha256",StudyFindingInventory.hash(sequence));m.put("provenance",Map.of("structure_url",url,"model_created_date",text(candidate.get("modelCreatedDate")),"metadata_query",reply.audit(),"coordinate_query",structure.audit(),"provider_sequence_start",candidate.getOrDefault("sequenceStart",1),"provider_sequence_end",candidate.getOrDefault("sequenceEnd",sequence.length())));
            String pae=text(candidate.get("paeDocUrl"));if(!pae.isBlank()){artifactUrl(pae);var error=client.getText(c,"AlphaFold DB",pae,AF,"Retain version-paired directional PAE for the exact retrieved model",integer(p,"max_file_bytes"));if(error.ok()){Path path=rawFolder.resolve("pae.json");Files.writeString(path,text(error.data()));m.put("pae",path.toAbsolutePath().toString());m.put("pae_provenance","Version-paired AlphaFold DB PAE: "+pae);}else m.put("pae_provenance","PAE unavailable: "+error.status());}models.add(StudyProteinInputs.model(m));}
        summary.put("retrieved_models",models.size());return models;
    }
    private Map<String,Object> assess(Context c,Map<String,Object> p,Map<String,Object> target,String sequence,Map<String,String> sequences,Map<String,Object> supplied,Path folder)throws IOException {
        var model=new LinkedHashMap<>(StudyProteinInputs.model(supplied));var sources=new LinkedHashMap<String,Object>();for(String field:StudyProteinInputs.MODEL_FILES)if(model.containsKey(field)){Path source=c.project().resolve(text(model.get(field)));if(!Files.isRegularFile(source))throw new IllegalArgumentException("Supply model "+field+": "+source);if(Files.size(source)>integer(p,"max_file_bytes"))throw new IllegalArgumentException("Model "+field+" exceeds max_file_bytes");String suffix=source.getFileName().toString();Path copy=StudyProteinInputs.snapshot(source,folder.resolve(field+"-"+suffix));sources.put(field,Map.of("source",source.toString(),"sha256",FollowupSupport.hash(copy)));model.put(field,copy.toString());}
        write(folder.resolve("model-source.yaml"),Map.of("declared_model",supplied,"file_sources",sources,"target_sequence_sha256",StudyFindingInventory.hash(sequence)));
        if(!model.containsKey("file"))throw new IllegalArgumentException("Protein confidence/PAE assessment needs its exact coordinate model");if(model.containsKey("source_sequence_sha256")&&!StudyFindingInventory.hash(sequence).equals(model.get("source_sequence_sha256")))throw new IllegalArgumentException("Model's declared source sequence hash differs from the target sequence");Path file=Path.of(text(model.get("file")));String format=text(model.get("format"));if(format.equals("auto")){String name=file.getFileName().toString().toLowerCase(java.util.Locale.ROOT);format=name.endsWith(".pdb")?"pdb":name.endsWith(".cif")||name.endsWith(".mmcif")?"cif":"";}
        Model parsed=ProteinStructure.parse(Files.readString(file),format,integer(model,"model_number"),"b_factor_plddt".equals(model.get("confidence_source")),integer(p,"max_residues"));if("residue_file".equals(model.get("confidence_source")))parsed=confidence(parsed,Path.of(text(model.get("confidence_file"))));Map<String,Integer> mapping=model.containsKey("residue_map")?residueMap(Path.of(text(model.get("residue_map"))),parsed):Map.of();String declared="";if(model.containsKey("model_sequence_id")){declared=sequences.get(text(model.get("model_sequence_id")));if(declared==null)throw new IllegalArgumentException("Unknown exact model_sequence_id in supplied FASTA");}
        Assessment a=ProteinStructure.assess(parsed,text(model.get("chain")),sequence,integer(model,"sequence_start"),mapping,declared);boolean exact=!a.sequenceMatch().equals("coordinate_identity_verified_partial_sequence_context")&&a.ambiguousAminoAcids()==0;var limitations=new ArrayList<String>();var assayMapping=map(target.get("assay_mapping"));String assayLimits=assayMapping.get("limitations") instanceof List<?> values?String.join("; ",values.stream().map(StudyPublicEvidence::text).toList()):text(assayMapping.get("limitations"));if(!assayLimits.isBlank())limitations.add("Declared assay limitation: "+assayLimits);if(!exact)limitations.add("Partial or ambiguous sequence context cannot establish complete isoform equivalence");String assay=text(map(target.get("assay_mapping")).getOrDefault("status","unknown"));if(!assay.equals("supplied_sequence"))limitations.add("Assay mapping "+assay+" is source-declared and does not establish sequence-specific measurement");if(a.coverage()<1)limitations.add("Missing coordinates remain unobserved; local confidence denominators use measured residues only");
        if(parsed.chains().size()>1)limitations.add("Multi-chain coordinate context; target chain assessed separately, interface correctness is unverified");
        var partnerChecks=new ArrayList<Object>();for(Object raw:list(target.get("partners"))){var partner=map(raw);String partnerSeq=sequences.get(text(partner.get("sequence_id")));if(partnerSeq==null)throw new IllegalArgumentException("Missing declared partner sequence");var check=ProteinStructure.assess(parsed,text(partner.get("chain")),partnerSeq,1,Map.of(),"");if(check.ambiguousAminoAcids()>0||!check.sequenceMatch().equals("exact_complete_coordinate_sequence")&&!check.sequenceMatch().equals("declared_full_polymer_with_partial_coordinates"))throw new IllegalArgumentException("Partner chain is not bound to its complete exact sequence");partnerChecks.add(Map.of("chain",check.chain(),"sequence_sha256",StudyFindingInventory.hash(partnerSeq),"sequence_match",check.sequenceMatch(),"coverage",check.coverage()));}write(folder.resolve("partner-context.yaml"),Map.of("checks",partnerChecks,"complex_justification",target.getOrDefault("complex_justification","Not a declared complex"),"interface_validated",false));
        var residueRows=new ArrayList<String[]>();for(var m:a.residues()){var r=m.residue();residueRows.add(new String[]{a.chain(),String.valueOf(m.sequencePosition()),String.valueOf(r.authorNumber()),r.insertion(),String.valueOf(r.aminoAcid()),value(r.plddt()),String.valueOf(r.x()),String.valueOf(r.y()),String.valueOf(r.z())});}FollowupSupport.table(folder.resolve("residues.tsv"),List.of("chain","sequence_position","residue_number","insertion_code","amino_acid","plddt","x","y","z"),residueRows);
        peptideAndVariant(target,sequence,a,folder);
        double[][] pae=null;int dimension=0;if(model.containsKey("pae")){if(text(model.get("pae_provenance")).isBlank())throw new IllegalArgumentException("Supplied PAE requires pae_provenance linking the matrix to this exact model/version");pae=matrix(Path.of(text(model.get("pae"))),integer(p,"max_pae_cells"));dimension=pae.length;var positions=paePositions(model,parsed,a,sequence,pae.length,mapping,declared);regions(target,sequence,a,pae,positions,folder,integer(p,"max_region_pairs"));}else limitations.add("PAE unavailable; domain/inter-residue placement uncertainty was not assessed");
        boolean eligible=(!Boolean.TRUE.equals(p.get("require_exact_sequence"))||exact)&&(!Boolean.TRUE.equals(p.get("require_plddt"))||a.confidenceResidues()==a.residues().size())&&(!Boolean.TRUE.equals(p.get("require_pae"))||pae!=null);if(Boolean.TRUE.equals(p.get("require_plddt"))&&a.confidenceResidues()!=a.residues().size())limitations.add("Required residue confidence is incomplete");if(Boolean.TRUE.equals(p.get("require_pae"))&&pae==null)limitations.add("Required PAE is missing");
        StudyProteinViews.write(folder,a,pae,integer(p,"plot_max_residues"));var row=new LinkedHashMap<String,Object>();for(String key:List.of("feature_id","dataset_id","protein_id","isoform_id","taxon_id","sequence_version"))row.put(key,target.getOrDefault(key,""));row.put("sequence_sha256",StudyFindingInventory.hash(sequence));row.put("model_id",model.get("id"));row.put("model_source",model.getOrDefault("source","supplied_model"));for(String key:List.of("structure_kind","method","model_version","seed"))row.put(key,model.getOrDefault(key,"unknown"));row.put("chain",a.chain());row.put("sequence_match",a.sequenceMatch());row.put("target_length",a.targetLength());row.put("observed_residues",a.residues().size());row.put("coverage",a.coverage());row.put("confidence_residues",a.confidenceResidues());row.put("mean_plddt",value(a.meanPlddt()));row.put("fraction_plddt_lt50",value(a.fractionVeryLow()));row.put("fraction_plddt_50_70",value(a.fractionLow()));row.put("fraction_plddt_70_90",value(a.fractionConfident()));row.put("fraction_plddt_ge90",value(a.fractionVeryHigh()));row.put("pae_dimension",dimension);row.put("assay_mapping_status",assay);row.put("assay_mapping_source",assayMapping.getOrDefault("source","Source not supplied; appraisal needed"));row.put("assay_mapping_limitations",assayLimits);row.put("source_sha256",map(sources.get("file")).get("sha256"));row.put("pae_sha256",model.containsKey("pae")?map(sources.get("pae")).get("sha256"):"");row.put("status",eligible?"eligible_context":"incomplete_context");row.put("limitations",String.join("; ",limitations)+"; "+CAVEAT);row.put("directory",relative(c,folder));write(folder.resolve("assessment.yaml"),row);return row;
    }
    private static Map<String,Integer> residueMap(Path file,Model model)throws IOException{var table=DelimitedData.readResult(file);var result=new LinkedHashMap<String,Integer>();var valid=new LinkedHashSet<String>();model.residues().forEach(r->valid.add(ProteinStructure.residueKey(r)));for(String[] row:table.rows()){String key=key(table,row);int position=Integer.parseInt(row[table.column("sequence_position")]);if(position<1||!valid.contains(key)||result.putIfAbsent(key,position)!=null)throw new IllegalArgumentException("Invalid, duplicate or orphan residue_map row");}return result;}
    private static Model confidence(Model model,Path file)throws IOException{var table=DelimitedData.readResult(file);var scores=new LinkedHashMap<String,Double>();var valid=new LinkedHashSet<String>();model.residues().forEach(r->valid.add(ProteinStructure.residueKey(r)));for(String[] row:table.rows()){String key=key(table,row);double value=Double.parseDouble(row[table.column("plddt")]);if(!valid.contains(key)||!Double.isFinite(value)||value<0||value>100||scores.putIfAbsent(key,value)!=null)throw new IllegalArgumentException("Invalid, duplicate or orphan pLDDT residue row");}var residues=new ArrayList<Residue>();for(var r:model.residues())residues.add(new Residue(r.chain(),r.modelPosition(),r.authorNumber(),r.insertion(),r.aminoAcid(),r.residueName(),r.x(),r.y(),r.z(),scores.getOrDefault(ProteinStructure.residueKey(r),Double.NaN)));return new Model(residues,model.polymerSequences(),model.modelNumbers(),model.format());}
    private static String key(DelimitedData table,String[] row){return row[table.column("chain")]+":"+row[table.column("residue_number")]+":"+(table.header().contains("insertion_code")?row[table.column("insertion_code")]:"");}
    private static double[][] matrix(Path file,int maximum)throws IOException{Object parsed=SimpleJson.parse(Files.readString(file));if(parsed instanceof List<?> l){if(l.size()!=1)throw new IllegalArgumentException("PAE JSON needs one explicitly paired matrix");parsed=l.get(0);}var object=map(parsed);Object raw=object.containsKey("predicted_aligned_error")?object.get("predicted_aligned_error"):object.get("pae");var rows=list(raw);if(rows.isEmpty()||(long)rows.size()*rows.size()>maximum)throw new IllegalArgumentException("Missing/oversized PAE matrix");double[][] matrix=new double[rows.size()][rows.size()];for(int i=0;i<rows.size();i++){var values=list(rows.get(i));if(values.size()!=rows.size())throw new IllegalArgumentException("PAE matrix must be square");for(int j=0;j<values.size();j++){if(!(values.get(j) instanceof Number n))throw new IllegalArgumentException("PAE cells must be numeric");matrix[i][j]=n.doubleValue();}}ProteinStructure.pae(matrix,List.of(),maximum);return matrix;}
    private static Map<Integer,Integer> paePositions(Map<String,Object> m,Model parsed,Assessment a,String target,int n,Map<String,Integer> mapping,String declared)throws IOException{var result=new LinkedHashMap<Integer,Integer>();if(m.containsKey("pae_index")){var table=DelimitedData.readResult(Path.of(text(m.get("pae_index"))));if(table.rows().size()!=n)throw new IllegalArgumentException("PAE index must enumerate every matrix token");var keys=new LinkedHashSet<String>();var indices=new LinkedHashSet<Integer>();var mapped=new LinkedHashMap<String,Integer>();a.residues().forEach(r->mapped.put(ProteinStructure.residueKey(r.residue()),r.sequencePosition()));for(String[] row:table.rows()){int index=Integer.parseInt(row[table.column("matrix_index")]);String key=key(table,row);if(index<1||index>n||!indices.add(index)||!keys.add(key))throw new IllegalArgumentException("Duplicate/out-of-range PAE token index");if(row[table.column("chain")].equals(a.chain())){Integer position=mapped.get(key);if(position==null)throw new IllegalArgumentException("PAE target token cannot be mapped to an identity-verified coordinate residue; supply a supported full sequence model");if(result.putIfAbsent(position,index-1)!=null)throw new IllegalArgumentException("Multiple PAE tokens map to one target residue");}}if(result.size()!=a.residues().size())throw new IllegalArgumentException("PAE token map omits observed target residues");}
        else{if(!mapping.isEmpty())throw new IllegalArgumentException("PAE paired with an explicit residue_map also requires an explicit pae_index; matrix token order is not inferred from remapped author numbering");if(parsed.chains().size()!=1)throw new IllegalArgumentException("Multi-chain PAE requires an explicit complete pae_index; chain order is never guessed");String polymer=declared.isEmpty()?parsed.polymerSequences().getOrDefault(a.chain(),""):declared;int start=integer(m,"sequence_start");if(polymer.isEmpty()){if(a.coverage()!=1||n!=target.length())throw new IllegalArgumentException("PAE length needs a declared full polymer sequence or a complete exact-coordinate sequence");polymer=target;}if(n!=polymer.length())throw new IllegalArgumentException("PAE dimension differs from the declared model sequence");for(int i=0;i<n;i++)result.put(start+i,i);if(!mapping.isEmpty())for(var residue:a.residues()){Integer index=result.get(residue.sequencePosition());if(index==null)throw new IllegalArgumentException("Explicit residue_map and PAE sequence indices disagree");}}
        return result;}
    private static void regions(Map<String,Object> target,String sequence,Assessment a,double[][] pae,Map<Integer,Integer> positions,Path folder,int maximum)throws IOException{var regions=new ArrayList<ProteinStructure.Region>();for(Object raw:list(target.get("regions"))){var r=map(raw);regions.add(new ProteinStructure.Region(text(r.get("id")),integer(r,"start"),integer(r,"end")));}if(regions.isEmpty())regions.add(new ProteinStructure.Region("full_target",1,sequence.length()));if((long)regions.size()*regions.size()>maximum)throw new IllegalArgumentException("Registered region pair family exceeds max_region_pairs; no region was dropped");long work=0;for(var r:regions)work+=r.end()-r.start()+1L;if(work*work>50000000L)throw new IllegalArgumentException("Complete directional region family exceeds the 50-million-cell work bound; no favorable region subset was selected");for(var r:regions)if(r.end()>sequence.length())throw new IllegalArgumentException("Protein region exceeds target sequence");var rows=new ArrayList<String[]>();for(var aligned:regions)for(var evaluated:regions){double mean=0,high=0;int count=0,xn=0,yn=0;for(int x=aligned.start();x<=aligned.end();x++)if(positions.containsKey(x))xn++;for(int y=evaluated.start();y<=evaluated.end();y++)if(positions.containsKey(y))yn++;for(int x=aligned.start();x<=aligned.end();x++)for(int y=evaluated.start();y<=evaluated.end();y++){Integer xi=positions.get(x),yi=positions.get(y);if(xi==null||yi==null)continue;double v=pae[xi][yi];count++;mean+=(v-mean)/count;high=Math.max(high,v);}rows.add(new String[]{aligned.id(),evaluated.id(),String.valueOf(xn),String.valueOf(aligned.end()-aligned.start()+1),String.valueOf(yn),String.valueOf(evaluated.end()-evaluated.start()+1),String.valueOf(count),count>0?value(mean):"NA",count>0?value(high):"NA","model_context_only"});}FollowupSupport.table(folder.resolve("region-pae.tsv"),List.of("aligned_region","evaluated_region","aligned_mapped_residues","aligned_target_residues","evaluated_mapped_residues","evaluated_target_residues","pairs","mean_pae_angstrom","maximum_pae_angstrom","interpretation"),rows);}
    private static void peptideAndVariant(Map<String,Object> target,String sequence,Assessment a,Path folder)throws IOException{var peptides=new ArrayList<String[]>();int ordinal=0;for(Object raw:list(map(target.get("assay_mapping")).get("peptides"))){String peptide=ProteinStructure.sequence(text(raw));var hits=ProteinStructure.peptidePositions(sequence,peptide);peptides.add(new String[]{String.valueOf(++ordinal),String.valueOf(peptide.length()),StudyFindingInventory.hash(peptide),String.valueOf(hits.size()),hits.toString(),hits.isEmpty()?"not_in_target":hits.size()>1?"multiple_target_positions":"one_target_position_not_proteomewide_unique"});}FollowupSupport.table(folder.resolve("peptide-context.tsv"),List.of("peptide_index","length","peptide_sha256","target_occurrences","target_positions","status"),peptides);
        var byPosition=new LinkedHashMap<Integer,ProteinStructure.Mapped>();a.residues().forEach(r->byPosition.put(r.sequencePosition(),r));var variants=new ArrayList<String[]>();for(Object raw:list(target.get("variants"))){var v=map(raw);int pos=integer(v,"position");if(pos>sequence.length()||sequence.charAt(pos-1)!=ProteinStructure.sequence(text(v.get("ref"))).charAt(0))throw new IllegalArgumentException("Protein variant REF does not match the exact target sequence");if(v.containsKey("genomic_variant")&&(text(v.get("mapping_provenance")).isBlank()||text(v.get("transcript_id")).isBlank()||!v.get("transcript_id").equals(target.get("transcript_id"))))throw new IllegalArgumentException("A genomic-to-protein variant mapping needs an exact matching transcript_id and mapping_provenance; genome coordinates are not translated by guesswork");var observed=byPosition.get(pos);variants.add(new String[]{text(v.get("id")),String.valueOf(pos),text(v.get("ref")),text(v.get("alt")),observed==null?"no_coordinates":"observed",observed==null?"NA":value(observed.residue().plddt()),"Source-declared residue/transcript mapping; confidence supplies context, not a predicted variant effect"});}FollowupSupport.table(folder.resolve("variant-context.tsv"),List.of("variant_id","sequence_position","ref","alt","coordinate_status","plddt","interpretation"),variants);}
    private static void accession(String id){if(!id.matches("[A-Z0-9]{6,10}(?:-[1-9][0-9]*)?"))throw new IllegalArgumentException("Public sequence/model retrieval needs an explicitly declared UniProt accession; arbitrary feature IDs are not sent");}
    private static void artifactUrl(String url){URI uri=URI.create(url);if(!"https".equals(uri.getScheme())||!"alphafold.ebi.ac.uk".equals(uri.getHost())||!uri.getPath().startsWith("/files/")||uri.getRawQuery()!=null||uri.getUserInfo()!=null||uri.getFragment()!=null||uri.getPort()!=-1)throw new IllegalArgumentException("AlphaFold artifact URL is outside its approved versioned files endpoint");}
    private static Map<String,Object> disposition(Map<String,Object> t,String status,String reason){var d=new LinkedHashMap<String,Object>();for(String key:List.of("feature_id","dataset_id","protein_id","isoform_id","taxon_id"))d.put(key,t.getOrDefault(key,""));d.put("status",status);d.put("reason",reason);return d;}
    private static int integer(Map<String,Object> map,String key){return ((Number)map.get(key)).intValue();}
    private static void increment(Map<String,Object> summary,String key){summary.put(key,((Number)summary.getOrDefault(key,0)).intValue()+1);}
    private static String value(double d){return Double.isFinite(d)?String.valueOf(d):"NA";}
    private static String relative(Context c,Path path){return c.outputDirectory().relativize(path).toString().replace('\\','/');}
    private static Result finish(Context c,Map<String,Object> p,Map<String,Object> summary,boolean complete,boolean performed,String message)throws IOException{summary.put("method_report",Map.of("operation",c.operation().get("type"),"performed",performed,"method","Exact-sequence protein C-alpha mapping, explicit confidence and directional PAE context","parameters",p,"software","JLinAlg "+JLinAlgCli.version(),"references",List.of(AF,UNIPROT,"https://github.com/google-deepmind/alphafold/blob/main/alphafold/model/modules.py"),"interpretation",message));summary.put("interpretation",message);if(!complete)summary.put("needs",List.of(StudyNeed.review("protein:"+c.operation().get("hypothesis"),"What is needed for the registered protein structure analysis?",message+"; inspect protein-analysis.yaml target/model dispositions",true).document()));write(c.outputDirectory().resolve("protein-analysis.yaml"),summary);var outputs=new ArrayList<String>();try(var files=Files.walk(c.outputDirectory())){for(Path file:files.filter(Files::isRegularFile).sorted().toList())outputs.add(relative(c,file));}return new Result(complete?State.COMPLETE:State.WAITING_FOR_INPUT,message,outputs,summary);}
}
